import csv
import io
import re
from typing import List, Dict, Any, Optional

def parse_csv(raw_csv: str):
    if raw_csv is None:
        raw_csv = ""
    text = raw_csv.lstrip("\ufeff")

    def split_physical_lines(s: str) -> List[str]:
        return s.splitlines()

    lines = split_physical_lines(text)

    def is_data_line(line: str) -> bool:
        if not line.strip():
            return False
        return bool(re.match(r'^\s*[^,]+(?:,|$)', line))

    start_idx = 0
    for i, line in enumerate(lines):
        if is_data_line(line):
            start_idx = i
            break
    else:
        return {"columns": [], "rows": []}

    data_text = "\n".join(lines[start_idx:])

    reader = csv.reader(io.StringIO(data_text), delimiter=",", quotechar='"', doublequote=True, skipinitialspace=False)
    rows = [row for row in reader]

    if not rows:
        return {"columns": [], "rows": []}

    max_width = max((len(r) for r in rows), default=0)
    if max_width == 0:
        return {"columns": [], "rows": []}

    normalized: List[List[str]] = []
    for row in rows:
        if len(row) < max_width:
            row = row + [""] * (max_width - len(row))
        elif len(row) > max_width:
            row = row[:max_width]
        normalized.append([str(v) for v in row])

    header_rows = 1
    header = normalized[0]
    data_rows = normalized[header_rows:]

    return {"columns": header, "rows": data_rows}
